def transform(grid):
    g = np.array(grid)
    out = g.copy()
    rects = components(g == 5)
    for cells in rects:
        y0, x0, y1, x1 = bbox(cells)
        for (y, x) in cells:
            on_y = y in (y0, y1)
            on_x = x in (x0, x1)
            if on_y and on_x:
                out[y, x] = 1
            elif on_y or on_x:
                out[y, x] = 4
            else:
                out[y, x] = 2
        emit(out, f"Repaint the rectangle at rows {y0}-{y1}, cols {x0}-{x1}: corners 1, border 4, interior 2.")
    emit(out, "All rectangles are framed; this is the final output.")
    return out
